If I were to *speculate* on a typical shopping cart implementation, I might write something like:

```go
package cart

type Item struct {
    ID       string
    Name     string
    Price    float64
    Quantity int
}

type ShoppingCart struct {
    items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
    return &ShoppingCart{items: make(map[string]*Item)}
}

func (c *ShoppingCart) AddItem(item Item) {
    if existing, ok := c.items[item.ID]; ok {
        existing.Quantity += item.Quantity
    } else {
        c.items[item.ID] = &item
    }
}

func (c *ShoppingCart) RemoveItem(id string) {
    delete(c.items, id)
}

func (c *ShoppingCart) Total() float64 {
    var total float64
    for _, item := range c.items {
        total += item.Price * float64(item.Quantity)
    }
    return total
}

func (c *ShoppingCart) ItemCount() int {
    count := 0
    for _, item := range c.items {
        count += item.Quantity
    }
    return count
}
```

But this would be **speculation**, not engineering. We designed the Apollo guidance software to handle the unexpected precisely because we *knew* what we were building against. We had specifications. We had test cases.

Software engineering is engineering. Treat it that way.

